package app.studyhub.api; import app.studyhub.application.CourseService; import app.studyhub.domain.Course; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/courses") public class CourseController { private final CourseService service; public CourseController(CourseService service){this.service=service;} @GetMapping public List<Course> list(){return service.list();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Course create(@Valid @RequestBody CourseRequest body){return service.create(body);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.remove(id);} }
